-- ArchiOffice asset pack load script (idempotent).
-- project_key = ARCHIOFFICE
-- Targets the aec.* schema created by 0001_core.sql / 0002_knowledge_graph.sql.
BEGIN;
DELETE FROM aec.kg_edges WHERE project_key = 'ARCHIOFFICE';
DELETE FROM aec.kg_aliases WHERE node_id IN (SELECT id FROM aec.kg_nodes WHERE project_key = 'ARCHIOFFICE');
DELETE FROM aec.kg_nodes WHERE project_key = 'ARCHIOFFICE';
-- GraphRAG registration: communities.detect() and ask.link() key off a Project node 'kg:p:<key>'.
-- link pack nodes to their aec.objects rows (object id == node id) so GraphRAG can cite them
UPDATE aec.kg_nodes n SET object_ids = ARRAY[o.id], document_ids = ARRAY[o.document_id] FROM aec.objects o WHERE o.id = n.id AND n.project_key = 'ARCHIOFFICE';
COMMIT;
